          "pattern": "mā · má · mǎ · mà · ma",
          "body": "Cada sílaba tiene un tono que cambia el significado. 1.º alto y plano (mā, madre), 2.º sube como una pregunta (má, cáñamo), 3.º baja y vuelve a subir (mǎ, caballo), 4.º cae con fuerza (mà, regañar). El tono neutro es corto y suave (ma). Truco: dos 3.º tonos seguidos → el primero se dice en 2.º: 你好 se escribe nǐ hǎo pero suena «ní hǎo».",
