    "title": "Moverse",
    "description": "Ir, llegar y orientarse",
    "color": "primary",
    "guide": {
      "intro": "Ir, llegar y orientarse. Aprendes a decir desde dónde y hasta dónde (从…到…), a qué distancia (离) y a la izquierda o a la derecha.",
      "culture": "Las bicis compartidas están por todas partes en las ciudades chinas: se desbloquean escaneando un código QR con el móvil y se dejan en cualquier esquina.",
      "notes": [
        {
          "title": "从…到…: desde… hasta…",
          "pattern": "从 + A + 到 + B",
          "body": "Sirve para lugares y para horas: 从北京到上海 (de Pekín a Shanghái), 从九点到五点 (de nueve a cinco).",
          "examples": [
            {
              "hanzi": "从这里到机场很远。",
              "pinyin": "Cóng zhèlǐ dào jīchǎng hěn yuǎn.",
              "meaning": "De aquí al aeropuerto hay mucha distancia."
            },
            {
              "hanzi": "我从九点到五点工作。",
              "pinyin": "Wǒ cóng jiǔ diǎn dào wǔ diǎn gōngzuò.",
              "meaning": "Trabajo de nueve a cinco."
            }
          ]
        },
        {
          "title": "离: a qué distancia",
          "pattern": "A + 离 + B + 很近 / 很远",
          "body": "A 离 B 近 = A está cerca de B. A 离 B 远 = A está lejos de B. Para preguntar: 离这里远吗?",
          "examples": [
            {
              "hanzi": "我家离学校很近。",
              "pinyin": "Wǒ jiā lí xuéxiào hěn jìn.",
              "meaning": "Mi casa está muy cerca de la escuela."
            }
          ]
        },
        {
          "title": "Posiciones: 左边, 右边, 旁边, 外",
          "pattern": "Lugar + (的) + posición",
          "body": "La posición va DETRÁS del lugar de referencia: 商店的右边 = a la derecha de la tienda, 门外 = fuera de la puerta. 进 = entrar, 出 = salir.",
          "examples": [
            {
              "hanzi": "医院在商店的右边。",
              "pinyin": "Yīyuàn zài shāngdiàn de yòubiān.",
              "meaning": "El hospital está a la derecha de la tienda."
            },
            {
              "hanzi": "请进房间。",
              "pinyin": "Qǐng jìn fángjiān.",
              "meaning": "Pase a la habitación, por favor."
            }
          ]
        }
      ]
    },
