    "id": "u14",
    "level": 2,
    "index": 6,
    "title": "Salud y deporte",
    "description": "El cuerpo, el médico y el ejercicio",
    "color": "info",
    "guide": {
      "intro": "El cuerpo, el médico y el deporte. Practicas cómo proponer planes con 吧 y cómo decir que alguien se ha puesto enfermo.",
      "culture": "Cada mañana, en los parques chinos, mucha gente practica taichí o baila en grupo (广场舞, «baile de plaza»). ¡Cualquiera puede unirse!",
      "notes": [
        {
          "title": "Proponer: 一起…吧",
          "pattern": "我们 + 一起 + verbo + 吧",
          "body": "一起 = juntos, y va antes del verbo. 吧 al final suaviza la frase y la convierte en una propuesta: «¡vamos a…!».",
          "examples": [
            {
              "hanzi": "我们一起去游泳吧。",
              "pinyin": "Wǒmen yìqǐ qù yóuyǒng ba.",
              "meaning": "Vamos a nadar juntos."
            },
            {
              "hanzi": "我们一起唱歌吧。",
              "pinyin": "Wǒmen yìqǐ chànggē ba.",
              "meaning": "¡Cantemos juntos!"
            }
          ]
        },
        {
          "title": "Cada deporte, su verbo",
          "pattern": "打篮球 · 踢足球 · 跑步 · 游泳",
          "body": "Los juegos de pelota con la mano usan 打 («golpear»): 打篮球 (baloncesto). Con el pie, 踢 («patear»): 踢足球 (fútbol). 跑步 (correr) y 游泳 (nadar) ya son verbos completos.",
          "examples": [
            {
              "hanzi": "他喜欢打篮球。",
              "pinyin": "Tā xǐhuan dǎ lánqiú.",
              "meaning": "Le gusta jugar al baloncesto."
            },
            {
              "hanzi": "我每天跑步。",
              "pinyin": "Wǒ měi tiān pǎobù.",
              "meaning": "Corro todos los días."
            }
          ]
        },
        {
          "title": "了 de cambio de estado",
          "pattern": "… + 了",
          "body": "了 al final indica que la situación es nueva: 他生病了 = se ha puesto enfermo (antes no lo estaba). 我好了 = ya estoy bien.",
          "examples": [
            {
              "hanzi": "我身体好了。",
              "pinyin": "Wǒ shēntǐ hǎo le.",
              "meaning": "Ya estoy bien de salud."
            },
            {
              "hanzi": "你吃药了吗？",
              "pinyin": "Nǐ chī yào le ma?",
              "meaning": "¿Te has tomado la medicina?"
            }
          ]
        }
      ]
    },
